/**
 * Brief presentation hold used only when the player receives damage.
 *
 * It scales scene presentation time without changing seeded run logic, UI,
 * input, or the raw clock. Successful player attacks never call this module.
 */

const MAX_HITSTOP_SECONDS = 0.06
const HELD_TIME_SCALE = 0

let remaining = 0
let frameScale = 1

/** Overlapping damage takes the longest hold instead of accumulating. */
export function requestHitstop(seconds: number): void {
  if (!Number.isFinite(seconds) || seconds <= 0) return
  remaining = Math.min(MAX_HITSTOP_SECONDS, Math.max(remaining, seconds))
}

/**
 * Latches this frame's presentation scale, then advances the raw hold clock.
 * This must be called once per frame, independent of the enemy count.
 */
export function tickHitstop(deltaSeconds: number): void {
  frameScale = remaining > 0 ? HELD_TIME_SCALE : 1
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0 || remaining <= 0)
    return
  remaining = Math.max(0, remaining - deltaSeconds)
}

/** Time scale for the current presentation frame. */
export function hitstopScale(): number {
  return frameScale
}

/** Returns a delta scaled by the current presentation hold. */
export function applyHitstop(deltaSeconds: number): number {
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return 0
  return deltaSeconds * hitstopScale()
}

export function isHitstopActive(): boolean {
  return remaining > 0
}

export function resetHitstop(): void {
  remaining = 0
  frameScale = 1
}
